1	//! (wave 4 of the compatibility track) The plugin 0.6.0 `claude` engine end to end through the real
2	//! `c3` binary against a FAKE claude CLI - `tests/fixtures/fake-claude.{cmd,ps1}`, the plugin's own
3	//! fake at v0.6.1 (driven by `FAKE_CLAUDE_*`, reached through the test hook
4	//! `CODEX_CONSULT_TEST_CHILD_ENV_PASS=FAKE_CLAUDE_` in test mode): the dry run's plan, a structured
5	//! run with its ledger evidence and the ALLOW-listed child environment, the lineage (resume pins the
6	//! resolved model, fork answers on a new session), the init proof and the model proof (E13), a
7	//! killed turn judged by its init (E12), a rejecting rate-limit event beside a successful result
8	//! (E15: the quota mark in the ledger, the machine-wide record and the listing), the endpoint route
9	//! (E3/E4), the roster's claude keys and the providers row; (wave 4f) the endpoint preflight's
10	//! launcher probe (F25-1) and its transcript guard (F25-2); (wave 4g) that probe in the endpoint
11	//! turn's environment minus its token (F32-1) and the fail-closed home derivation (F32-2).
12	//!
13	//! GUARD: every child gets a scratch USERPROFILE/HOME and a PATH without any directory that holds a
14	//! claude launcher, so the real CLI can never start; the fake logs every start. Nothing reaches a
15	//! real provider or intake. Windows only (the fake is a `.cmd` wrapper around a PowerShell script).
16	#![cfg(windows)]
17	
18	use std::path::{Path, PathBuf};
19	use std::process::{Command, Output};
20	
21	use serde_json::Value;
22	
23	const FAKE_CMD: &str = include_str!("fixtures/fake-claude.cmd");
24	const FAKE_PS1: &str = include_str!("fixtures/fake-claude.ps1");
25	const ADVISE: &str = r#"{"schema_version":"1","verdict":"ADVISE","verdict_reason":"r","reply_markdown":"m","findings":[],"prior_findings":[],"unproven":[],"first_run_checklist":[]}"#;
26	const UUID_RE: &str = r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$";
27	
28	fn c3_bin() -> PathBuf {
29	    PathBuf::from(env!("CARGO_BIN_EXE_c3"))
30	}
31	
32	fn git(repo: &Path, args: &[&str]) {
33	    let st = Command::new("git")
34	        .arg("-C")
35	        .arg(repo)
36	        .args(args)
37	        .output()
38	        .expect("git on PATH");
39	    assert!(st.status.success(), "git {args:?}");
40	}
41	
42	/// A PATH without any directory that holds a claude launcher (GUARD).
43	fn safe_path() -> String {
44	    let path = std::env::var("PATH").unwrap_or_default();
45	    path.split(';')
46	        .filter(|d| {
47	            !d.is_empty()
48	                && !["claude", "claude.exe", "claude.cmd", "claude.ps1"]
49	                    .iter()
50	                    .any(|n| Path::new(d).join(n).exists())
51	        })
52	        .collect::<Vec<_>>()
53	        .join(";")
54	}
55	
56	struct Env {
57	    work: PathBuf,
58	    repo: PathBuf,
59	    home: PathBuf,
60	    fake: PathBuf,
61	    reply: PathBuf,
62	    log: PathBuf,
63	}
64	
65	fn setup(tag: &str) -> Env {
66	    setup_named(tag, "repo")
67	}
68	
69	/// [`setup`] with the repository's directory named `repo_name`.
70	fn setup_named(tag: &str, repo_name: &str) -> Env {
71	    let nanos = std::time::SystemTime::now()
72	        .duration_since(std::time::UNIX_EPOCH)
73	        .map(|d| d.as_nanos())
74	        .unwrap_or(0);
75	    let work = std::env::temp_dir().join(format!("c3-w4-{tag}-{}-{nanos}", std::process::id()));
76	    let repo = work.join(repo_name);
77	    std::fs::create_dir_all(&repo).unwrap();
78	    git(&repo, &["init", "-q"]);
79	    git(&repo, &["config", "user.email", "t@e.com"]);
80	    git(&repo, &["config", "user.name", "T"]);
81	    std::fs::write(repo.join("app.txt"), "one\n").unwrap();
82	    git(&repo, &["add", "-A"]);
83	    git(&repo, &["commit", "-q", "-m", "init"]);
84	    std::fs::create_dir_all(repo.join(".collab").join("t").join("handoffs")).unwrap();
85	    let home = work.join("codexhome");
86	    std::fs::create_dir_all(&home).unwrap();
87	    std::fs::write(home.join("config.toml"), "model = \"gpt-5.1\"\n").unwrap();
88	    std::fs::create_dir_all(work.join("userhome").join("AppData").join("Local")).unwrap();
89	    std::fs::create_dir_all(work.join("claude-config")).unwrap();
90	    let fake = work.join("fake-claude.cmd");
91	    std::fs::write(&fake, FAKE_CMD.replace("\r\n", "\n").replace('\n', "\r\n")).unwrap();
92	    std::fs::write(work.join("fake-claude.ps1"), FAKE_PS1).unwrap();
93	    let reply = work.join("advise.json");
94	    std::fs::write(&reply, ADVISE).unwrap();
95	    let log = work.join("argv.jsonl");
96	    Env {
97	        work,
98	        repo,
99	        home,
100	        fake,
101	        reply,
102	        log,
103	    }
104	}
105	
106	impl Env {
107	    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Command {
108	        let mut cmd = Command::new(c3_bin());
109	        for (k, _) in std::env::vars() {
110	            if k.starts_with("CODEX_CONSULT_")
111	                || k.starts_with("FAKE_")
112	                || k.starts_with("C3_")
113	                || k.starts_with("ANTHROPIC_")
114	                || k.starts_with("CLAUDE")
115	            {
116	                cmd.env_remove(&k);
117	            }
118	        }
119	        let uh = self.work.join("userhome");
120	        cmd.current_dir(&self.repo)
121	            .env("PATH", safe_path())
122	            .env("CODEX_HOME", &self.home)
123	            .env("HOME", &uh)
124	            .env("USERPROFILE", &uh)
125	            .env("LOCALAPPDATA", uh.join("AppData").join("Local"))
126	            .env("CLAUDE_CONFIG_DIR", self.work.join("claude-config"))
127	            .env("CODEX_CONSULT_CLAUDE_EXE", &self.fake)
128	            .env("CODEX_CONSULT_TEST_MODE", "1")
129	            .env("CODEX_CONSULT_TEST_CHILD_ENV_PASS", "FAKE_CLAUDE_")
130	            .env("CODEX_CONSULT_ROSTER", "none")
131	            .env("CODEX_CONSULT_HEALTH", "none")
132	            .env("CODEX_CONSULT_TELEMETRY", "off")
133	            .env("C3_TELEMETRY_HUB", "http://127.0.0.1:9/T")
134	            .env("C3_PRIORS", "off")
135	            .env("FAKE_CLAUDE_ARGV_LOG", &self.log)
136	            .env("FAKE_CLAUDE_REPLY", &self.reply);
137	        for (k, v) in env {
138	            if v.is_empty() {
139	                cmd.env_remove(k);
140	            } else {
141	                cmd.env(k, v);
142	            }
143	        }
144	        cmd.args(args);
145	        cmd
146	    }
147	
148	    fn c3(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
149	        let _ = std::fs::remove_file(&self.log);
150	        self.cmd(args, env).output().expect("run c3")
151	    }
152	
153	    fn consult(&self, extra: &[&str], env: &[(&str, &str)]) -> Output {
154	        let mut args = vec![
155	            "consult",
156	            "--task",
157	            "t",
158	            "--prompt",
159	            "Check the %APPDATA% words",
160	        ];
161	        args.extend_from_slice(extra);
162	        self.c3(&args, env)
163	    }
164	
165	    fn ledger(&self) -> Vec<Value> {
166	        let p = self.repo.join(".collab").join("t").join("sessions.json");
167	        match std::fs::read_to_string(p) {
168	            Ok(t) => serde_json::from_str::<Value>(&t).unwrap()["codex"]["consults"]
169	                .as_array()
170	                .unwrap()
171	                .clone(),
172	            Err(_) => Vec::new(),
173	        }
174	    }
175	
176	    fn last(&self) -> Value {
177	        self.ledger().last().cloned().unwrap()
178	    }
179	
180	    /// The fake's starts of the last call: `(kind, record)`.
181	    fn starts(&self) -> Vec<Value> {
182	        std::fs::read_to_string(&self.log)
183	            .unwrap_or_default()
184	            .lines()
185	            .filter(|l| !l.trim().is_empty())
186	            .map(|l| serde_json::from_str::<Value>(l).unwrap())
187	            .collect()
188	    }
189	
190	    fn turns(&self) -> Vec<Value> {
191	        self.starts()
192	            .into_iter()
193	            .filter(|s| s["kind"] == "turn")
194	            .collect()
195	    }
196	
197	    fn roster(&self, json: &str) -> String {
198	        let p = self.work.join("roster.json");
199	        std::fs::write(&p, json).unwrap();
200	        p.to_string_lossy().to_string()
201	    }
202	}
203	
204	fn text(o: &Output) -> String {
205	    format!(
206	        "{}{}",
207	        String::from_utf8_lossy(&o.stdout),
208	        String::from_utf8_lossy(&o.stderr)
209	    )
210	    .replace("\r\n", "\n")
211	}
212	
213	fn arg_of(rec: &Value, flag: &str) -> String {
214	    let a = rec["argv"].as_array().cloned().unwrap_or_default();
215	    for i in 0..a.len().saturating_sub(1) {
216	        if a[i] == flag {
217	            return a[i + 1].as_str().unwrap_or("").to_string();
218	        }
219	    }
220	    String::new()
221	}
222	
223	fn has_name(rec: &Value, name: &str) -> bool {
224	    rec["env"]
225	        .as_array()
226	        .map(|a| {
227	            a.iter()
228	                .any(|v| v.as_str().is_some_and(|s| s.eq_ignore_ascii_case(name)))
229	        })
230	        .unwrap_or(false)
231	}
232	
233	fn strs(v: &Value) -> Vec<String> {
234	    v.as_array()
235	        .map(|a| {
236	            a.iter()
237	                .filter_map(|x| x.as_str().map(|s| s.to_string()))
238	                .collect()
239	        })
240	        .unwrap_or_default()
241	}
242	
243	fn is_uuid(s: &str) -> bool {
244	    regex::Regex::new(UUID_RE).unwrap().is_match(s)
245	}
246	
247	// ------------------------------------------------------------------ DRYRUN
248	
249	#[test]
250	fn a_dry_run_plans_the_restricted_turn_and_starts_no_turn() {

