            } else {
                '-'
            }
        })
        .collect();
    out.truncate(60);
    if out.is_empty() {
        out.push('x');
    }
    out
}

/// The next record directory of a task: `<work>/<NN>-<provider>-<model>` with NN the next
/// 2-digit sequence (never one that exists).
pub fn allocate(
    work_root: &Path,
    provider: &str,
    model: &str,
) -> Result<(String, i64, PathBuf), String> {
    let next = run_dirs(work_root)
        .iter()
