// ------------------------------------------------------------------ --status / --wait

/// One work run as the query sees it.
struct WorkRun {
    id: String,
    record: Option<RunRecord>,
    error: String,
}

fn read_runs(work_root: &Path) -> Vec<WorkRun> {
    run_dirs(work_root)
        .into_iter()
        .map(|(_, dir)| {
            let (record, error) = match read_record(&dir) {
                Ok(r) => (r, String::new()),
                Err(e) => (None, e),
            };
            let id = record.as_ref().map(|r| r.id.clone()).unwrap_or_else(|| {
                dir.file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .to_string()
            });
            WorkRun { id, record, error }
        })
        .collect()
}

/// The exit code of a status listing: 2 while any run is running, else 1 when one
/// died/timed out/was refused/unreadable, else 0 (an empty task is 0 too).
fn exit_of(runs: &[WorkRun]) -> i32 {
    for r in runs {
        let st = r
            .record
            .as_ref()
            .map(|x| x.status.as_str())
            .unwrap_or("unreadable");
        if st == "running" {
            return 2;
        }
    }
    for r in runs {
        let st = r
            .record
            .as_ref()
            .map(|x| x.status.as_str())
            .unwrap_or("unreadable");
        if st != "done" {
            return 1;
        }
    }
    0
}

